import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-css-css-fundamentals-for-visually-appealing-web":{"intro":"In this lab, we will explore the fundamentals of CSS (Cascading Style Sheets) programming. This lab will cover the basics of CSS syntax, selectors, properties, and values. By the end of this lab, you will have a solid foundation in CSS programming and be able to create visually appealing web pages.","steps":[{"title":"Alternating Text","body":["To create an alternating text animation, follow these steps:","• Create a <span> element with a class of \"alternating\" and an id of \"alternating-text\" to hold the text that will be alternated:","• In the CSS, define an animation called alternating-text that will make the <span> element disappear by setting display: none:","• In JavaScript, define an array of the different words that will be alternated and use the first word to initialize the content of the <span> element:"],"code":[{"lang":"html","text":"<p>I love coding in <span class=\"alternating\" id=\"alternating-text\"></span>.</p>"},{"lang":"css","text":".alternating {\n  animation-name: alternating-text;\n  animation-duration: 3s;\n  animation-iteration-count: infinite;\n  animation-timing-function: ease;\n}\n\n@keyframes alternating-text {\n  90% {\n    display: none;\n  }\n}"},{"lang":"js","text":"const texts = [\"Java\", \"Python\", \"C\", \"C++\", \"C#\", \"Javascript\"];\nconst element = document.getElementById(\"alternating-text\");\n\nlet i = 0;\nelement.innerHTML = texts[0];"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Alternating Text</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n    <script src=\"./script.js\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-responsive-container-aspect-ratio-css":{"intro":"In this lab, we will learn how to create a responsive container with a specified aspect ratio using CSS. You will be introduced to the --aspect-ratio custom property and how to use the calc() function to calculate the container's height. You will also learn how to set the child element to maintain the aspect ratio using the object-fit: cover property. By the end of this lab, you will have a better understanding of how to create visually appealing and responsive containers on your web pages.","steps":[{"title":"Aspect Ratio","body":["This code creates a responsive container with a specific aspect ratio using CSS custom properties and calc() function. Follow these steps to achieve this:","• Define the desired aspect ratio using a CSS custom property, --aspect-ratio. • Set the container element's position property to relative and its height property to 0. • Calculate the container element's height using the calc() function and the --aspect-ratio custom property, and set it as the padding-bottom property. • Set the direct child of the container element to position: absolute, top: 0, left: 0, width: 100%, and height: 100%. • Maintain the aspect ratio of the child element by setting its object-fit property to cover.","Use the following HTML and CSS code to create the container:"],"code":[{"lang":"css","text":".container {\n  --aspect-ratio: 16/9;\n  position: relative;\n  height: 0;\n  padding-bottom: calc(100% / var(--aspect-ratio));\n}\n\n.container > * {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Aspect Ratio</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-border-with-top-triangle":{"intro":"In this lab, we will be learning how to create a content container with a triangle at the top using CSS. This is a common design element used in many websites and applications to add visual interest and create a sense of hierarchy. By the end of this lab, you will have the skills to create this effect and apply it to your own projects.","steps":[{"title":"Border with Top Triangle","body":["To create a content container with a triangle at the top, follow these steps:","• Use the ::before and ::after pseudo-elements to create two triangles. • Set the border-color and background-color of the triangles to match the container. • Set the border-width of the ::before triangle to be 1px wider than the ::after triangle to act as the border. • Position the ::after triangle 1px to the right of the ::before triangle to allow for the left border to be shown.","Here is an example HTML code for the container:","And here is the corresponding CSS code:"],"code":[{"lang":"css","text":".container {\n  position: relative;\n  background: #ffffff;\n  padding: 15px;\n  border: 1px solid #dddddd;\n  margin-top: 20px;\n}\n\n.container::before,\n.container::after {\n  content: \"\";\n  position: absolute;\n  bottom: 100%;\n  left: 19px;\n  border: 11px solid transparent;\n}\n\n.container::before {\n  border-bottom-color: #dddddd;\n}\n\n.container::after {\n  left: 20px;\n  border: 10px solid transparent;\n  border-bottom-color: #ffffff;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Border With Top Triangle</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-bouncing-css-animation-loader":{"intro":"In this lab, we will be exploring the world of CSS animations by creating a bouncing loader animation. This lab is designed to help you understand how to use @keyframes to define animations, how to apply animations to elements using CSS, and how to control the timing and direction of animations. By the end of this lab, you will have a better understanding of how to create engaging and dynamic animations using CSS.","steps":[{"title":"Bouncing Loader","body":["To create a bouncing loader animation:","• Define a @keyframes animation that uses the opacity and transform properties, with a single axis translation on transform: translate3d() for better performance. • Create a parent container with the class .bouncing-loader that uses display: flex and justify-content: center to center the bouncing circles. • Give the three <div> elements for the bouncing circles the same width, height, and border-radius: 50% to make them circular. • Apply the bouncing-loader animation to each of the three bouncing circles. • Use a different animation-delay for each circle and animation-direction: alternate to create the appropriate effect."],"code":[{"lang":"css","text":"@keyframes bouncing-loader {\n  to {\n    opacity: 0.1;\n    transform: translate3d(0, -16px, 0);\n  }\n}\n\n.bouncing-loader {\n  display: flex;\n  justify-content: center;\n}\n\n.bouncing-loader > div {\n  width: 16px;\n  height: 16px;\n  margin: 3rem 0.2rem;\n  background: #8385aa;\n  border-radius: 50%;\n  animation: bouncing-loader 0.6s infinite alternate;\n}\n\n.bouncing-loader > div:nth-child(2) {\n  animation-delay: 0.2s;\n}\n\n.bouncing-loader > div:nth-child(3) {\n  animation-delay: 0.4s;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Bouncing Loader</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-box-sizing-reset-in-css":{"intro":"In this lab, we will explore the concept of Box-Sizing Reset in CSS programming. The lab will cover how to reset the box-model and prevent the width and height of an element from being affected by border or padding. By the end of the lab, you will have a thorough understanding of the box-sizing property and how it can be used to enhance the design of your web pages.","steps":[{"title":"Box-Sizing Reset","body":["To ensure that the width and height of an element are not affected by border or padding, use the box-sizing: border-box CSS property. This includes the padding and border in the calculation of the element's width and height. If you want to inherit the box-sizing property from a parent element, use box-sizing: inherit.","Here's an example of using box-sizing property with two div elements:","In this example, the first div element has box-sizing: border-box, and the second div element has box-sizing: content-box."],"code":[{"lang":"css","text":"*,\n*::before,\n*::after {\n  box-sizing: inherit;\n}\n\n.box {\n  display: inline-block;\n  width: 120px;\n  height: 120px;\n  padding: 8px;\n  margin: 8px;\n  background: #f24333;\n  color: white;\n  border: 1px solid #ba1b1d;\n  border-radius: 4px;\n  box-sizing: border-box;\n}\n\n.content-box {\n  box-sizing: content-box;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Box-Sizing Reset</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-fallback-for-images-that-fail-to-load":{"intro":"In this lab, we will learn how to apply styles to the img element to display an error message and the image URL when an image fails to load. We will use the ::before and ::after pseudo-elements to create a user-friendly fallback for images that cannot be displayed. By the end of this lab, you will be able to enhance user experience by providing helpful information in case of image loading failures.","steps":[{"title":"Fallback for Images That Fail to Load","body":["Fallback for Images That Fail to Load","When an image fails to load, display an error message to the user. To do this, apply styles to the img element as if it were a text container, setting its display to block and its width to 100%. Use the ::before and ::after pseudo-elements to respectively display the error message and the image URL. These elements will only be shown if the image fails to load.","Here's an example code snippet:"],"code":[{"lang":"html","text":"<img src=\"https://nowhere.to.be/found.jpg\" />"},{"lang":"css","text":"img {\n  display: block;\n  width: 100%;\n  height: auto;\n  line-height: 2;\n  position: relative;\n  text-align: center;\n  font-family: sans-serif;\n  font-weight: 300;\n}\n\nimg::before {\n  content: \"Sorry, this image is unavailable.\";\n  display: block;\n  margin-bottom: 8px;\n}\n\nimg::after {\n  content: \"(url: \" attr(src) \")\";\n  display: block;\n  font-size: 12px;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Fallback for Images That Fail to Load</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-button-border-animation":{"intro":"In this lab, we will explore how to create a button border animation on hover using CSS. By using the ::before and ::after pseudo-elements, we can add two boxes above and below the button and transition their width to 100% on hover. This lab will help you to enhance your CSS skills and add interactivity to your web pages.","steps":[{"title":"Button Border Animation","body":["To create a border animation on hover, you can use the ::before and ::after pseudo-elements to generate two boxes that are 24px wide and positioned above and below the box. Then, apply the :hover pseudo-class to increase the width of those elements to 100% on hover and animate the transition using transition.","Here's an example code snippet:"],"code":[{"lang":"html","text":"<button class=\"animated-border-button\">Submit</button>"},{"lang":"css","text":".animated-border-button {\n  background-color: #263059;\n  border: none;\n  color: #ffffff;\n  outline: none;\n  padding: 12px 40px 10px;\n  position: relative;\n}\n\n.animated-border-button::before,\n.animated-border-button::after {\n  border: 0 solid transparent;\n  transition: all 0.3s;\n  content: \"\";\n  height: 0;\n  position: absolute;\n  width: 24px;\n}\n\n.animated-border-button::before {\n  border-top: 2px solid #263059;\n  right: 0;\n  top: -4px;\n}\n\n.animated-border-button::after {\n  border-bottom: 2px solid #263059;\n  bottom: -4px;\n  left: 0;\n}\n\n.animated-border-button:hover::before,\n.animated-border-button:hover::after {\n  width: 100%;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Button Border Animation</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-button-swing-animation":{"intro":"In this lab, we will explore CSS programming by learning how to create and modify stylesheets to control the appearance of web pages. You will gain hands-on experience with various CSS properties and selectors to create visually appealing and responsive designs. By the end of the lab, you will have a solid understanding of CSS and be able to apply your knowledge to create professional-looking websites.","steps":[{"title":"Button Swing Animation","body":["To create a swing animation on focus, you should use an appropriate transition to animate changes to the element. Then, apply the :focus pseudo-class to the element and use animation with transform to make it swing. Finally, add animation-iteration-count to play the animation only once. Here is an example of how to do this in HTML and CSS:"],"code":[{"lang":"html","text":"<button class=\"button-swing\">Submit</button>"},{"lang":"css","text":".button-swing {\n  color: #65b5f6;\n  background-color: transparent;\n  border: 1px solid #65b5f6;\n  border-radius: 4px;\n  padding: 0 16px;\n  cursor: pointer;\n  transition: all 0.2s ease-in-out;\n}\n\n.button-swing:focus {\n  animation: swing 1s ease;\n  animation-iteration-count: 1;\n}\n\n@keyframes swing {\n  15% {\n    transform: translateX(5px);\n  }\n  30% {\n    transform: translateX(-5px);\n  }\n  50% {\n    transform: translateX(3px);\n  }\n  65% {\n    transform: translateX(-3px);\n  }\n  80% {\n    transform: translateX(2px);\n  }\n  100% {\n    transform: translateX(0);\n  }\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Button Swing Animation</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-button-fill-animation":{"intro":"In this lab, we will learn how to create a fill animation on hover for a button using CSS. We will use the :hover pseudo-class to change the background and color of the button when the user hovers over it, and also add a transition effect to animate the changes. By the end of this lab, you will be able to enhance the user experience on your website by adding engaging hover effects to your buttons.","steps":[{"title":"Button Fill Animation","body":["To create a fill animation on hover, you can set the color and background properties and apply an appropriate transition to animate the changes. To trigger the animation on hover, use the :hover pseudo-class to change the background and color properties of the element. Here's an example code snippet:"],"code":[{"lang":"html","text":"<button class=\"animated-fill-button\">Submit</button>"},{"lang":"css","text":".animated-fill-button {\n  padding: 20px;\n  background: #fff;\n  color: #000;\n  border: 1px solid #000;\n  cursor: pointer;\n  transition: 0.3s all ease-in-out;\n}\n\n.animated-fill-button:hover {\n  background: #000;\n  color: #fff;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Button Fill Animation</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-button-grow-animation":{"intro":"In this lab, we will learn how to create a button with a grow animation on hover using CSS. This effect can be used to add interactivity and visual interest to a website or application. By applying the transform property and :hover pseudo-class, we can make the button scale up when the user hovers over it, creating a subtle but effective animation.","steps":[{"title":"Button Grow Animation","body":["To create a grow animation on hover, you can use an appropriate transition to animate changes to the element. Use the :hover pseudo-class to change the transform property to scale(1.1). This will grow the element when the user hovers over it.","Here is an example code snippet you can use:"],"code":[{"lang":"html","text":"<button class=\"button-grow\">Submit</button>"},{"lang":"css","text":".button-grow {\n  color: #65b5f6;\n  background-color: transparent;\n  border: 1px solid #65b5f6;\n  border-radius: 4px;\n  padding: 0 16px;\n  cursor: pointer;\n  transition: all 0.3s ease-in-out;\n}\n\n.button-grow:hover {\n  transform: scale(1.1);\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Button Grow Animation</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-button-shrink-animation":{"intro":"In this lab, we will explore how to create a button shrink animation using CSS. The purpose of this lab is to help you understand how to use the :hover pseudo-class and transition property to create a smooth and visually appealing animation when a user hovers over a button. By the end of this lab, you will have a good understanding of how to create simple yet effective animations using CSS.","steps":[{"title":"Button Shrink Animation","body":["To create a shrink animation on hover for an element, you can use an appropriate transition property to animate changes and the :hover pseudo-class to trigger the animation. For example, if you want to shrink a button with class button-shrink when a user hovers over it, you can add the following CSS:","This will apply a transition effect to all properties of the button when there is a change, and when the user hovers over it, the button will shrink to 80% of its original size. The HTML code for the button is as follows:"],"code":[{"lang":"css","text":".button-shrink {\n  color: #65b5f6;\n  background-color: transparent;\n  border: 1px solid #65b5f6;\n  border-radius: 4px;\n  padding: 0 16px;\n  cursor: pointer;\n  transition: all 0.3s ease-in-out;\n}\n\n.button-shrink:hover {\n  transform: scale(0.8);\n}"},{"lang":"html","text":"<button class=\"button-shrink\">Submit</button>"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Button Shrink Animation</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-card-with-image-cutout":{"intro":"In this lab, we will learn how to create a card with an image cutout using HTML and CSS. This lab will teach you how to add a colored background to a container element, create a card with an image and other content, and use the ::before pseudo-element to add a border around the figure element, creating the illusion of a cutout in the card. By the end of this lab, you will have a solid understanding of how to create visually appealing cards with image cutouts.","steps":[{"title":"Card with Image Cutout","body":["To create a card with an image cutout, follow these steps:","• Add a colored background to a .container element using the background property. • Create a .card element and add a figure element inside it with the desired image and any other content. • Use the ::before pseudo-element to add a border around the figure element. Set the border color to match the .container element's background color to create the illusion of a cutout in the .card.","Here is an example HTML code for the card:","And here is the corresponding CSS code:"],"code":[{"lang":"css","text":".container {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  padding: 96px 24px 48px;\n  background: #f3f1fe;\n}\n\n.card {\n  width: 350px;\n  margin: 8px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  background: #fff;\n  border-radius: 10px;\n  box-shadow: 0 0 5px -2px rgba(0, 0, 0, 0.1);\n}\n\n.card figure {\n  width: 120px;\n  height: 120px;\n  margin-top: -60px;\n  border-radius: 50%;\n  position: relative;\n}\n\n.card figure::before {\n  content: \"\";\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 100%;\n  height: 100%;\n  transform: translate(-50%, -50%);\n  border-radius: inherit;\n  border: 1rem solid #f3f1fe;\n  box-shadow: 0 1px rgba(0, 0, 0, 0.1);\n}\n\n.card figure img {\n  width: 100%;\n  height: 100%;\n  border-radius: inherit;\n  object-fit: cover;\n}\n\n.card .content {"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Card With Image Cutout</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-checkerboard-background-pattern":{"intro":"In this lab, we will explore the world of CSS programming and learn how to create a checkerboard background pattern using advanced CSS techniques. The lab will guide you through the steps required to create a visually appealing checkerboard pattern that can be used in various web design projects. By the end of this lab, you will have gained valuable experience in using CSS to create beautiful and engaging web designs.","steps":[{"title":"Understanding the Project Files","body":["Understanding the Project Files","The initial HTML file should look like this:","• Now open the style.css file in the editor.","The initial CSS file should be empty or contain minimal styles:"],"code":[{"lang":"html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Checkerboard Pattern</title>\n    <link rel=\"stylesheet\" href=\"style.css\" />\n  </head>\n  <body>\n    <!-- You will add your code here -->\n  </body>\n</html>"},{"lang":"css","text":"/* CSS styles will be added here */"}]},{"title":"Creating the HTML Structure","body":["Now that we understand our project files, let's create the HTML structure for our checkerboard pattern.","• Open the index.html file in the editor again.","• We need to add a container element for our checkerboard pattern. Inside the <body> tag, replace the comment with a <div> element that has a class of \"checkerboard\":","• Now, let's add some basic CSS to define the dimensions of our checkerboard. Open the style.css file and add the following code:"],"code":[{"lang":"html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Checkerboard Pattern</title>\n    <link rel=\"stylesheet\" href=\"style.css\" />\n  </head>\n  <body>\n    <div class=\"checkerboard\"></div>\n  </body>\n</html>"},{"lang":"css","text":".checkerboard {\n  width: 240px;\n  height: 240px;\n  background-color: #fff;\n}"}]},{"title":"Creating the First Gradient","body":["Now we'll start creating our checkerboard pattern using CSS gradients. Let's add the first linear gradient to create part of the pattern.","Understanding CSS Linear Gradients","CSS linear gradients allow you to create smooth transitions between two or more colors in a straight line. The linear-gradient() function takes an angle and a series of color stops as parameters. We'll use this technique to create our checkerboard squares.","• Let's modify our .checkerboard class to include the first linear gradient:"],"code":[{"lang":"css","text":".checkerboard {\n  width: 240px;\n  height: 240px;\n  background-color: #fff;\n  background-image: linear-gradient(\n    45deg,\n    #000 25%,\n    transparent 25%,\n    transparent 75%,\n    #000 75%,\n    #000\n  );\n  background-size: 60px 60px;\n}"}]},{"title":"Completing the Checkerboard Pattern","body":["Completing the Checkerboard Pattern","Now let's add the second linear gradient to complete our checkerboard pattern and make it repeatable across the entire element.","• Open the style.css file again.","• Modify the .checkerboard class to include a second linear gradient that will create the alternating pattern:"],"code":[{"lang":"css","text":".checkerboard {\n  width: 240px;\n  height: 240px;\n  background-color: #fff;\n  background-image:\n    linear-gradient(\n      45deg,\n      #000 25%,\n      transparent 25%,\n      transparent 75%,\n      #000 75%,\n      #000\n    ),\n    linear-gradient(\n      -45deg,\n      #000 25%,\n      transparent 25%,\n      transparent 75%,\n      #000 75%,\n      #000\n    );\n  background-size: 60px 60px;\n  background-repeat: repeat;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Checkerboard Background Pattern</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-css-styling-techniques-for-web-development":{"intro":"In this lab, we will explore CSS programming by practicing different techniques to style HTML elements. Through hands-on exercises, we will learn how to use selectors, properties, and values to create visually appealing web pages. By the end of this lab, you will have a solid understanding of CSS and be able to apply it to your own web development projects.","steps":[{"title":"Circle","body":["To create a circular shape using pure CSS, use the border-radius: 50% property to curve the element's borders. Make sure to set both width and height to the same value to ensure a perfect circle. If different values are used, an ellipse will be created instead. Here's an example code snippet:"],"code":[{"lang":"css","text":".circle {\n  border-radius: 50%;\n  width: 32px;\n  height: 32px;\n  background: #9c27b0;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Circle</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-css-clearfix-technique":{"intro":"In this lab, we will learn about the clearfix technique in CSS. This technique is used to ensure that an element clears its floated children. We will explore how to implement this technique in our code and discuss its limitations. By the end of this lab, you will have a solid understanding of how to use clearfix in your CSS layouts.","steps":[{"title":"Clearfix","body":["To ensure that an element self-clears its children when using float to build layouts, you can use the ::after pseudo-element and apply content: '' to allow it to affect layout. Additionally, use clear: both to make the element clear past both left and right floats. However, this technique only works properly if there are no non-floating children in the container and there are no tall floats before the clearfixed container but in the same formatting context (e.g. floated columns). For example:","Note that using a more modern approach, such as the flexbox or grid layout, is recommended over using float to build layouts."],"code":[{"lang":"css","text":".clearfix::after {\n  content: \"\";\n  display: block;\n  clear: both;\n}\n\n.floated {\n  float: left;\n  padding: 4px;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Clearfix</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-constant-width-to-height-ratio":{"intro":"In this lab, we will explore how to create a constant width to height ratio for elements with varying widths. By using the padding-top property on a ::before pseudo-element, we can ensure that the height of the element remains proportionate to its width. This technique can be used to create responsive squares and other shapes with specific aspect ratios.","steps":[{"title":"Constant Width to Height Ratio","body":["Constant Width to Height Ratio","This code snippet ensures that an element with variable width will retain a proportionate height value. To achieve this, apply padding-top on the ::before pseudo-element, making the height of the element equal to a percentage of its width. The proportion of height to width can be altered as necessary. For example, a padding-top of 100% will create a responsive square with a 1:1 ratio. To use this code, simply add the following HTML code:","Then, add the following CSS code:"],"code":[{"lang":"css","text":".constant-width-to-height-ratio {\n  background: #9c27b0;\n  width: 50%;\n}\n\n.constant-width-to-height-ratio::before {\n  content: \"\";\n  padding-top: 100%;\n  float: left;\n}\n\n.constant-width-to-height-ratio::after {\n  content: \"\";\n  display: block;\n  clear: both;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Constant Width to Height Ratio</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-nested-list-counters-with-css":{"intro":"In this lab, we will explore the use of CSS counters to create custom list counters. Specifically, we will learn how to initialize and increment counter variables, and how to display the value of these variables using the counters() function. By the end of this lab, you will be able to create nested list counters and customize the appearance of list elements using CSS.","steps":[{"title":"Counter","body":["To create a custom list counter that accounts for nested list elements, follow these steps:","• Use counter-reset to initialize a variable counter (default 0), with the name being the value of the attribute (e.g. counter). • Use counter-increment on the variable counter for each countable element (e.g. each <li>). • Use counters() to display the value of each variable counter as part of the content of the ::before pseudo-element for each countable element (e.g. each <li>). The second value passed to it ('.') acts as the delimiter for nested counters.","And here is the CSS code to apply the custom list counter:"],"code":[{"lang":"html","text":"<ul>\n  <li>List item</li>\n  <li>List item</li>\n  <li>\n    List item\n    <ul>\n      <li>List item</li>\n      <li>List item</li>\n      <li>List item</li>\n    </ul>\n  </li>\n</ul>"},{"lang":"css","text":"ul {\n  counter-reset: counter;\n  list-style: none;\n}\n\nli::before {\n  counter-increment: counter;\n  content: counters(counter, \".\") \" \";\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Counter</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-animated-checkbox-styling-with-css":{"intro":"In this lab, we will learn how to use CSS to create custom checkboxes with animation on state change. We will use an SVG element to create the check symbol, flexbox to layout the checkboxes, and CSS animations to create a zoom effect. By the end of this lab, you will have the skills to create stylish and interactive checkboxes for your web projects.","steps":[{"title":"Custom Checkbox","body":["To create a styled checkbox with animation on state change:","• Create a check symbol as an <svg> element with a <symbol> element inside. Use the <use> element to insert it as a reusable SVG icon. • Create a container div with a class of .checkbox-container. Use flexbox to create the appropriate layout for the checkboxes. • Hide the <input> element and associate a label with it to display a checkbox and the provided text. • To animate the check symbol on state change, use stroke-dashoffset. • To create a zoom animation effect, use transform: scale(0.9) via a CSS animation."],"code":[{"lang":"html","text":"<svg class=\"checkbox-symbol\">\n  <symbol id=\"check\" viewbox=\"0 0 12 10\">\n    <polyline\n      points=\"1.5 6 4.5 9 10.5 1\"\n      stroke-linecap=\"round\"\n      stroke-linejoin=\"round\"\n      stroke-width=\"2\"\n    ></polyline>\n  </symbol>\n</svg>\n\n<div class=\"checkbox-container\">\n  <input class=\"checkbox-input\" id=\"apples\" type=\"checkbox\" />\n  <label class=\"checkbox\" for=\"apples\">\n    <span>\n      <svg width=\"12px\" height=\"10px\">\n        <use xlink:href=\"#check\"></use>\n      </svg>\n    </span>\n    <span>Apples</span>\n  </label>\n  <input class=\"checkbox-input\" id=\"oranges\" type=\"checkbox\" />\n  <label class=\"checkbox\" for=\"oranges\">\n    <span>\n      <svg width=\"12px\" height=\"10px\">\n        <use xlink:href=\"#check\"></use>\n      </svg>\n    </span>\n    <span>Oranges</span>\n  </label>\n</div>"},{"lang":"css","text":".checkbox-symbol {\n  position: absolute;\n  width: 0;\n  height: 0;\n  pointer-events: none;\n  user-select: none;\n}\n\n.checkbox-container {\n  box-sizing: border-box;\n  background: #ffffff;\n  color: #222;\n  height: 64px;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  flex-flow: row wrap;\n}\n\n.checkbox-container * {\n  box-sizing: border-box;\n}\n\n.checkbox-input {\n  position: absolute;\n  visibility: hidden;\n}\n\n.checkbox {\n  user-select: none;\n  cursor: pointer;\n  padding: 6px 8px;\n  border-radius: 6px;\n  overflow: hidden;\n  transition: all 0.3s ease;\n  display: flex;\n}\n\n.checkbox:not(:last-child) {\n  margin-right: 6px;\n}\n\n.checkbox:hover {\n  background: rgba(0, 119, 255, 0.06);\n}\n\n.checkbox span {\n  vertical-align: middle;"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Custom Checkbox</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-custom-radio-button":{"intro":"In this lab, we will explore CSS programming concepts by creating a custom radio button with animation on state change. The lab will guide you through the process of using flexbox to create a layout for the radio buttons, resetting the styles on the <input> element, and using the ::before element to create the inner circle of the radio button. By the end of the lab, you will have a better understanding of CSS styling and animation techniques.","steps":[{"title":"Custom Radio Button","body":["To create a styled radio button with animation on state change, follow these steps:","• Create a .radio-container using flexbox to create the appropriate layout for the radio buttons. • Reset the styles on the <input> and use it to create the outline and background of the radio button. • Use the ::before element to create the inner circle of the radio button. • Create an animation effect on state change by using transform: scale(1) and a CSS transition.","Here is an example HTML snippet:","And here is the corresponding CSS:"],"code":[{"lang":"css","text":".radio-container {\n  display: flex;\n  align-items: center;\n}\n\n.radio-container * {\n  box-sizing: border-box;\n}\n\n.radio-input {\n  appearance: none;\n  width: 16px;\n  height: 16px;\n  margin: 0;\n  border: 1px solid #cccfdb;\n  border-radius: 50%;\n  display: grid;\n  align-items: center;\n  justify-content: center;\n  transition: all 0.3s ease;\n}\n\n.radio-input::before {\n  content: \"\";\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  transform: scale(0);\n  transition: 0.3s transform ease-in-out;\n  box-shadow: inset 6px 6px #ffffff;\n}\n\n.radio-input:checked {\n  background: #0077ff;\n  border-color: #0077ff;\n}\n\n.radio-input:checked::before {\n  transform: scale(1);\n}\n\n.radio {\n  cursor: pointer;\n  padding: 6px 8px;\n  margin-right: 6px;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Custom Radio Button</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-customizing-scrollbar-styles-with-css":{"intro":"In this lab, we will be exploring how to customize the scrollbar style using CSS. We will use the ::-webkit-scrollbar property to style the scrollbar, including the scrollbar track and thumb. By the end of this lab, you will have a better understanding of how to create custom scrollbars and enhance the user experience of your website.","steps":[{"title":"Custom Scrollbar","body":["To customize the scrollbar style for elements with scrollable overflow, you can use ::-webkit-scrollbar to style the scrollbar element, ::-webkit-scrollbar-track to style the scrollbar track (the background of the scrollbar), and ::-webkit-scrollbar-thumb to style the scrollbar thumb (the draggable element). However, note that this technique only works on WebKit-based browsers, and scrollbar styling is not on any standards track. Here is an example of how to use these selectors in HTML and CSS:"],"code":[{"lang":"css","text":".custom-scrollbar {\n  height: 70px;\n  overflow-y: scroll;\n}\n\n.custom-scrollbar::-webkit-scrollbar {\n  width: 8px;\n}\n\n.custom-scrollbar::-webkit-scrollbar-track {\n  background: #1e3f20;\n  border-radius: 12px;\n}\n\n.custom-scrollbar::-webkit-scrollbar-thumb {\n  background: #4a7856;\n  border-radius: 12px;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Custom Scrollbar</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-custom-text-selection":{"intro":"In this lab, we will explore the world of CSS programming and learn how to style web pages using various CSS properties and selectors. The purpose of this lab is to provide hands-on experience to beginners and intermediate level developers to enhance their skills in creating visually appealing web pages. Through this lab, you will also learn how to troubleshoot common CSS issues and use best practices in your coding.","steps":[{"title":"Custom Text Selection","body":["To modify the style of selected text, utilize the ::selection pseudo-selector. Here's an example code snippet to select and style text within a paragraph element:"],"code":[{"lang":"html","text":"<p class=\"custom-text-selection\">Select some of this text.</p>"},{"lang":"css","text":"::selection {\n  background: aquamarine;\n  color: black;\n}\n\n.custom-text-selection::selection {\n  background: deeppink;\n  color: white;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Custom Text Selection</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-display-table-centering":{"intro":"In this lab, we will learn how to center a child element within its parent element using display: table. By using this technique, we can easily achieve both vertical and horizontal centering without having to resort to complex positioning or JavaScript. This is a useful skill to have when designing responsive layouts for websites and applications.","steps":[{"title":"Display Table Centering","body":["To center a child element both vertically and horizontally within its parent element, follow these steps:","• Add a container element with a fixed height and width.","• Add the child element inside the container element and give it a class of .center.","• In the CSS, apply the following styles to the container element:"],"code":[{"lang":"css","text":".container {\n  border: 1px solid #9c27b0;\n  height: 250px;\n  width: 250px;\n}"},{"lang":"css","text":".center {\n  display: table;\n  height: 100%;\n  width: 100%;\n}\n\n.center > span {\n  display: table-cell;\n  text-align: center;\n  vertical-align: middle;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Display Table Centering</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-css-techniques-for-visually-appealing-design":{"intro":"In this lab, we will delve into the world of CSS programming and explore various techniques to enhance the design and layout of web pages. Through a series of exercises and challenges, you will learn how to use CSS selectors, properties, and values to style HTML elements and create visually appealing web pages. By the end of the lab, you will have gained a solid foundation in CSS programming and be able to apply your newfound knowledge to create stunning websites.","steps":[{"title":"Donut Spinner","body":["To indicate the loading of content, create a donut spinner with a semi-transparent border for the whole element. Exclude one side to serve as the loading indicator for the donut. Then, define and use an appropriate animation, using transform: rotate() to rotate the element. Here's an example code in HTML and CSS:"],"code":[{"lang":"css","text":"@keyframes donut-spin {\n  0% {\n    transform: rotate(0deg);\n  }\n  100% {\n    transform: rotate(360deg);\n  }\n}\n\n.donut {\n  display: inline-block;\n  border: 4px solid rgba(0, 0, 0, 0.1);\n  border-left-color: #7983ff;\n  border-radius: 50%;\n  width: 30px;\n  height: 30px;\n  animation: donut-spin 1.2s linear infinite;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Donut Spinner</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-stylish-drop-cap-technique":{"intro":"In this lab, we will learn about the Drop Cap technique in CSS. Drop Cap is a typographic technique used to add visual appeal to the first letter of the first paragraph. Through this lab, you will understand how to use the :first-child selector and the ::first-letter pseudo-element to style the first letter of a paragraph in a unique and eye-catching way.","steps":[{"title":"Drop Cap","body":["> You can write the code in index.html and style.css.","Makes the first letter of the first paragraph bigger than the rest of the text.","• Use the :first-child selector to select only the first paragraph. • Use the ::first-letter pseudo-element to style the first element of the paragraph."],"code":[{"lang":"html","text":"<p>\n  Lorem ipsum dolor sit amet, consectetur adipiscing elit. Aliquam commodo\n  ligula quis tincidunt cursus. Integer consectetur tempor ex eget hendrerit.\n  Cras facilisis sodales odio nec maximus. Pellentesque lacinia convallis\n  libero, rhoncus tincidunt ante dictum at. Nullam facilisis lectus tellus, sit\n  amet congue erat sodales commodo.\n</p>\n<p>\n  Donec magna erat, imperdiet non odio sed, sodales tempus magna. Integer vitae\n  orci lectus. Nullam consectetur orci at pellentesque efficitur.\n</p>"},{"lang":"css","text":"p:first-child::first-letter {\n  color: #5f79ff;\n  float: left;\n  margin: 0 8px 0 4px;\n  font-size: 3rem;\n  font-weight: bold;\n  line-height: 1;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Drop Cap</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-dynamic-css-shadows-creation":{"intro":"In this lab, we will explore how to create dynamic shadows using CSS. You will learn how to use the ::after pseudo-element and various CSS properties such as background, filter, opacity, and z-index to create an effect that mimics a box-shadow, but is based on the colors of the element itself. By the end of this lab, you will be able to add an extra layer of depth and dimensionality to your designs.","steps":[{"title":"Dynamic Shadow","body":["To create a shadow that is based on the colors of an element, follow these steps:","• Use the ::after pseudo-element with position: absolute and width and height set to 100% to fill the available space in the parent element.","• Inherit the background of the parent element by using background: inherit.","• Slightly offset the pseudo-element using top. Then, use filter: blur() to create a shadow, and set opacity to make it semi-transparent."],"code":[{"lang":"css","text":".dynamic-shadow {\n  position: relative;\n  width: 10rem;\n  height: 10rem;\n  background: linear-gradient(75deg, #6d78ff, #00ffb8);\n  z-index: 1;\n}\n\n.dynamic-shadow::after {\n  content: \"\";\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: inherit;\n  top: 0.5rem;\n  filter: blur(0.4rem);\n  opacity: 0.7;\n  z-index: -1;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Dynamic Shadow</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-crafting-etched-text-effects-with-css":{"intro":"In this lab, we will be learning how to create an 'etched' or engraved text effect using CSS. This effect can add a unique and stylish touch to your web designs, and it's surprisingly easy to achieve. By adjusting the shadow, background, and text color, we can create the illusion of text being carved into the background. Join us as we explore this fun and creative technique!","steps":[{"title":"Etched Text","body":["To create an \"etched\" or engraved effect for text on a background, use the following CSS properties:","The text-shadow property creates a white shadow offset 0px horizontally and 2px vertically from the origin position. Make sure that the background is darker than the shadow for the effect to work. Additionally, the text color should be slightly faded to make it look like it's been carved out of the background. Finally, apply the etched-text class to the desired HTML element, such as a paragraph, to achieve the effect."],"code":[{"lang":"css","text":".etched-text {\n  text-shadow: 0 2px white;\n  font-size: 1.5rem;\n  font-weight: bold;\n  color: #b8bec5;\n}"},{"lang":"html","text":"<p class=\"etched-text\">I appear etched into the background.</p>"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Etched Text</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-evenly-distributed-children":{"intro":"In this lab, we will explore the basics of CSS programming and learn how to apply styles to HTML documents. Through a series of hands-on exercises, you will learn how to create and modify CSS rules, use selectors to target specific elements, and apply styles to text, backgrounds, and borders. By the end of this lab, you will have a solid understanding of CSS and be able to use it to create visually appealing web pages.","steps":[{"title":"Evenly Distributed Children","body":["To evenly distribute child elements within a parent element, use the flexbox layout by setting the parent element's display property to flex. To distribute the children horizontally with equal space between them, use justify-content: space-between. To distribute the children with space around them, use justify-content: space-around. Here's an example:"],"code":[{"lang":"css","text":".evenly-distributed-children {\n  display: flex;\n  justify-content: space-between;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Evenly Distributed Children</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-fit-image-in-container":{"intro":"In this lab, we will learn how to use CSS to fit and position images within their containers while preserving their aspect ratio. We will explore the object-fit and object-position properties and how they can be used to achieve different results. By the end of this lab, you will be able to create visually appealing images that fit perfectly within their designated space.","steps":[{"title":"Fit Image in Container","body":["To fit an image inside its container while preserving its aspect ratio, you can use object-fit: contain. To fill the container with the image while preserving its aspect ratio, use object-fit: cover. If you want to position the image at the center of the container, you can use object-position: center.","Here's an example of how you can use these properties:"],"code":[{"lang":"html","text":"<img class=\"image image-contain\" src=\"https://picsum.photos/600/200\" />\n<img class=\"image image-cover\" src=\"https://picsum.photos/600/200\" />"},{"lang":"css","text":".image {\n  background: #34495e;\n  border: 1px solid #34495e;\n  width: 200px;\n  height: 200px;\n}\n\n.image-contain {\n  object-fit: contain;\n  object-position: center;\n}\n\n.image-cover {\n  object-fit: cover;\n  object-position: right top;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Fit Image in Container</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-responsive-flexbox-centering-techniques":{"intro":"In this lab, we will explore the concept of flexbox centering in CSS. You will learn how to horizontally and vertically center child elements within a parent element using flexbox. By the end of this lab, you will be able to create responsive and visually appealing layouts using flexbox centering techniques.","steps":[{"title":"Flexbox Centering","body":["To center a child element both horizontally and vertically within a parent element using flexbox, follow these steps:","• Create a flexbox layout by setting the parent element's display property to flex. • Use the justify-content property to center the child horizontally by setting its value to center. • Use the align-items property to center the child vertically by setting its value to center. • Add the child element within the parent element.","Here's an example code snippet:"],"code":[{"lang":"css","text":".flexbox-centering {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  height: 100px;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Flexbox Centering</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-list-with-floating-section-headings":{"intro":"In this lab, we will explore the fundamentals of CSS programming and learn how to create beautiful and responsive web layouts. Through hands-on exercises, we will cover topics such as CSS selectors, box model, and positioning, as well as advanced techniques like flexbox and grid. By the end of this lab, you will have the skills and knowledge to create stunning websites that look great on any device.","steps":[{"title":"List with Floating Section Headings","body":["List With Floating Section Headings","To create a list with floating headings for each section, follow these steps:","• Apply overflow-y: auto to the list container to allow for vertical overflow. • Use display: grid on the inner container (<dl>) to create a layout with two columns. • Set headings (<dt>) to grid-column: 1 and content (<dd>) to grid-column: 2. • Finally, apply position: sticky and top: 0.5rem to headings to create a floating effect."],"code":[{"lang":"css","text":".container {\n  display: grid;\n  place-items: center;\n  min-height: 400px;\n}\n\n.floating-stack {\n  background: #455a64;\n  color: #fff;\n  height: 80vh;\n  width: 320px;\n  border-radius: 1rem;\n  overflow-y: auto;\n}\n\n.floating-stack > dl {\n  margin: 0 0 1rem;\n  display: grid;\n  grid-template-columns: 2.5rem 1fr;\n  align-items: center;\n}\n\n.floating-stack dt {\n  position: sticky;\n  top: 0.5rem;\n  left: 0.5rem;\n  font-weight: bold;\n  background: #263238;\n  color: #cfd8dc;\n  height: 2rem;\n  width: 2rem;\n  border-radius: 50%;\n  padding: 0.25rem 1rem;\n  grid-column: 1;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  box-sizing: border-box;\n}\n\n.floating-stack dd {\n  grid-column: 2;\n  margin: 0;\n  padding: 0.75rem;\n}\n\n.floating-stack > dl:first-of-type > dd:first-of-type {\n  margin-top: 0.25rem;"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>List With Floating Section Headings</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-enhancing-form-interactivity-with-css-focus-":{"intro":"In this lab, we will explore the :focus-within pseudo-class in CSS, which allows us to apply styles to a parent element when any of its child elements are focused. We will use this feature to create a visually appealing form that changes its appearance when the user interacts with it. Through this lab, you will gain a better understanding of how to enhance the user experience by using CSS to create interactive forms.","steps":[{"title":"Focus Within","body":["To change the appearance of a form when any of its child elements are focused, use the pseudo-class :focus-within to apply styles to the parent element. For example, in the given HTML code, if any of the input fields are focused, the form element will have a green background. To apply styles to the child elements, use appropriate CSS selectors like label and input."],"code":[{"lang":"html","text":"<form>\n  <label for=\"username\">Username:</label>\n  <input id=\"username\" type=\"text\" />\n  <br />\n  <label for=\"password\">Password:</label>\n  <input id=\"password\" type=\"text\" />\n</form>"},{"lang":"css","text":"form {\n  border: 2px solid #52b882;\n  padding: 8px;\n  border-radius: 2px;\n}\n\nform:focus-within {\n  background: #7cf0bd;\n}\n\nlabel {\n  display: inline-block;\n  width: 72px;\n}\n\ninput {\n  margin: 4px 12px;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Focus Within</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-fundamentals-of-css-styling":{"intro":"In this lab, we will explore the fundamentals of CSS programming. You will learn how to use CSS to style web pages and create visually appealing designs. By the end of this lab, you will have a solid understanding of CSS syntax, selectors, and properties, and be able to apply them to your own projects.","steps":[{"title":"Full-Width Image","body":["> You can write the code in index.html and style.css..","• Use left: 50% and right: 50% to position the image in the middle of the parent element. • Use margin-left: -50vw and margin-right: -50vw to offset the image on both sides relative to the size of the viewport. • Use width: 100vw and max-width: 100vw to size the image relative to the viewport."],"code":[{"lang":"html","text":"<main>\n  <h4>Lorem ipsum dolor sit amet</h4>\n  <p>\n    Lorem ipsum dolor sit amet, consectetur adipiscing elit. Mauris molestie\n    lobortis sapien, sit amet iaculis est interdum tincidunt. Nunc egestas nibh\n    ut metus elementum consequat. Integer elit orci, rhoncus efficitur lectus\n    eu, faucibus interdum felis.\n  </p>\n  <p>\n    <img class=\"full-width\" src=\"https://picsum.photos/id/257/2560/1440.jpg\" />\n  </p>\n  <p>\n    Orci varius natoque penatibus et magnis dis parturient montes, nascetur\n    ridiculus mus. Nullam pretium lectus sed ex efficitur, ac varius sapien\n    gravida. Sed facilisis elit quis sem sollicitudin, ut aliquam neque\n    eleifend. Maecenas sagittis neque sapien, ac tempus nulla tempus nec.\n    Curabitur tellus est, convallis id dolor ut, porta hendrerit quam.\n  </p>\n</main>"},{"lang":"css","text":"main {\n  margin: 0 auto;\n  max-width: 640px;\n}\n\nimg {\n  height: auto;\n  max-width: 100%;\n}\n\n.full-width {\n  position: relative;\n  left: 50%;\n  right: 50%;\n  margin-left: -50vw;\n  margin-right: -50vw;\n  max-width: 100vw;\n  width: 100vw;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Full-Width Image</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-fullscreen-element-styling-with-css":{"intro":"In this lab, we will explore how to use the :fullscreen CSS pseudo-element selector to apply styles to an element when it is in fullscreen mode. We will create a button using Element.requestFullscreen() to make the element fullscreen for the purpose of previewing the style. By the end of this lab, you will have a better understanding of how to create fullscreen elements with custom styles using CSS.","steps":[{"title":"Fullscreen","body":["To style an element in fullscreen mode, you can use the :fullscreen CSS pseudo-element selector. You can also create a button that makes the element fullscreen for preview purposes using a <button> and Element.requestFullscreen(). Here's an example code:"],"code":[{"lang":"css","text":".container {\n  margin: 40px auto;\n  max-width: 700px;\n}\n\n.element {\n  padding: 20px;\n  height: 300px;\n  width: 100%;\n  background-color: skyblue;\n  box-sizing: border-box;\n}\n\n.element p {\n  text-align: center;\n  color: white;\n  font-size: 3em;\n}\n\n/* For Internet Explorer */\n.element:-ms-fullscreen p {\n  visibility: visible;\n}\n\n/* For modern browsers */\n.element:fullscreen {\n  background-color: #e4708a;\n  width: 100vw;\n  height: 100vh;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Fullscreen</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-creating-gradient-text-with-css":{"intro":"In this lab, we will explore the concept of gradient text in CSS. The purpose of this lab is to help you understand how to create gradient text using the linear-gradient() function, as well as how to use the webkit-text-fill-color and webkit-background-clip properties to fill the text with a gradient background. By the end of this lab, you will be able to create visually appealing gradient text that can enhance the design of your web pages.","steps":[{"title":"Gradient Text","body":["To give text a gradient color, you can use CSS properties. First, use the background property with a linear-gradient() value to give the text element a gradient background. Then, use webkit-text-fill-color: transparent to fill the text with a transparent color. Finally, use webkit-background-clip: text to clip the background with the text and fill the text with the gradient background as the color. Here's an example code snippet:"],"code":[{"lang":"html","text":"<p class=\"gradient-text\">Gradient text</p>"},{"lang":"css","text":".gradient-text {\n  background: linear-gradient(#70d6ff, #00072d);\n  -webkit-text-fill-color: transparent;\n  -webkit-background-clip: text;\n  font-size: 32px;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Gradient Text</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-centered-grid-layout-mastery":{"intro":"In this lab, we will explore the concept of grid centering using CSS. You will learn how to horizontally and vertically center a child element within a parent element using the grid layout. By the end of this lab, you will have a solid understanding of how to use justify-content and align-items properties to create a perfectly centered layout.","steps":[{"title":"Grid Centering","body":["To center a child element both horizontally and vertically within a parent element, follow these steps:","• Create a grid layout using display: grid. • Use justify-content: center to center the child horizontally. • Use align-items: center to center the child vertically.","Here's an example HTML structure:"],"code":[{"lang":"css","text":".parent {\n  display: grid;\n  justify-content: center;\n  align-items: center;\n  height: 100px;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Grid Centering</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-css-fundamentals-for-web-styling":{"intro":"In this lab, we will be exploring the fundamentals of CSS programming. The purpose of this lab is to help you gain a solid understanding of CSS syntax, selectors, properties, and values. By completing this lab, you will be able to style HTML elements and create visually appealing web pages.","steps":[{"title":"Hamburger Button","body":["To create a hamburger menu that transitions to a cross button on hover, follow these steps:","• Use a .hamburger-menu container div which contains the top, bottom, and middle bars. • Set the container to display: flex with flex-flow: column wrap. • Add distance between the bars using justify-content: space-between. • Use transform: rotate() to rotate the top and bottom bars by 45 degrees and opacity: 0 to fade the middle bar on hover. • Use transform-origin: left so that the bars rotate around the left point.","Here's the corresponding HTML code:"],"code":[{"lang":"css","text":".hamburger-menu {\n  display: flex;\n  flex-flow: column wrap;\n  justify-content: space-between;\n  height: 2.5rem;\n  width: 2.5rem;\n  cursor: pointer;\n}\n\n.hamburger-menu .bar {\n  height: 5px;\n  background: black;\n  border-radius: 5px;\n  margin: 3px 0px;\n  transform-origin: left;\n  transition: all 0.5s;\n}\n\n.hamburger-menu:hover .top {\n  transform: rotate(45deg);\n}\n\n.hamburger-menu:hover .middle {\n  opacity: 0;\n}\n\n.hamburger-menu:hover .bottom {\n  transform: rotate(-45deg);\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Hamburger Button</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-smooth-transition-of-dynamic-heights":{"intro":"In this lab, we will explore how to smoothly transition an element's height from 0 to auto when its height is unknown. This technique is useful for creating dropdown menus, accordions, and other animated content. By using CSS transition, max-height, and overflow properties, as well as JavaScript to dynamically set the height value, we can create a seamless and visually appealing user experience.","steps":[{"title":"Height Transition","body":["This code snippet transitions an element's height from 0 to auto when its height is unknown by performing the following steps:","• Use the transition property to specify that changes to max-height should be transitioned over a duration of 0.3s. • Use the overflow property set to hidden to prevent the contents of the hidden element from overflowing its container. • Use the max-height property to specify an initial height of 0. • Use the :hover pseudo-class to change the max-height to the value of the --max-height variable set by JavaScript. • Use the Element.scrollHeight property and CSSStyleDeclaration.setProperty() method to set the value of --max-height to the current height of the element. • **Note:** This approach causes reflow on each animation…"],"code":[{"lang":"css","text":".el {\n  transition: max-height 0.3s;\n  overflow: hidden;\n  max-height: 0;\n}\n\n.trigger:hover > .el {\n  max-height: var(--max-height);\n}"},{"lang":"js","text":"let el = document.querySelector(\".el\");\nlet height = el.scrollHeight;\nel.style.setProperty(\"--max-height\", height + \"px\");"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Height Transition</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n    <script src=\"./script.js\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-hide-scroll-bars":{"intro":"In this lab, we will explore the concept of hiding scrollbars on an element while still allowing it to be scrollable using CSS. We will use the overflow: auto property to enable scrolling, and scrollbar-width: none to hide scrollbars on Firefox, and display: none on the ::-webkit-scrollbar pseudo-element to hide scrollbars on WebKit browsers. This lab will provide a hands-on experience in implementing this CSS technique to improve user experience on scrollable elements.","steps":[{"title":"Hide Scroll Bars","body":["To allow an element to be scrollable while hiding the scrollbars, follow these steps:","• Use overflow: auto to enable scrolling on the element. • Use scrollbar-width: none to hide the scrollbars on Firefox. • Use display: none on the ::-webkit-scrollbar pseudo-element to hide the scrollbars on WebKit browsers (such as Chrome, Edge, and Safari).","Here's an example implementation:"],"code":[{"lang":"css","text":".scrollable {\n  width: 200px;\n  height: 100px;\n  overflow: auto;\n  scrollbar-width: none;\n}\n\n/* Hide scrollbars on WebKit browsers */\n.scrollable::-webkit-scrollbar {\n  display: none;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Hide Scroll Bars</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-image-gallery-with-horizontal-scroll":{"intro":"In this lab, we will delve into the world of CSS programming to create a responsive image gallery with a horizontal scroll. The purpose of this lab is to teach you how to use CSS properties to create a visually appealing and interactive gallery that allows users to scroll through images seamlessly. By the end of this lab, you will have a solid understanding of how to create a horizontal scrollable image gallery using CSS.","steps":[{"title":"Image Gallery with Horizontal Scroll","body":["Image Gallery With Horizontal Scroll","Here are the instructions for creating a horizontally scrollable image gallery:","Here is the HTML code for the gallery:","Here is the CSS code for the gallery:"],"code":[{"lang":"css","text":".gallery-container {\n  position: relative;\n  display: flex;\n  justify-content: center;\n}\n\n.thumbnails {\n  position: absolute;\n  bottom: 8px;\n  display: flex;\n  flex-direction: row;\n  gap: 6px;\n}\n\n.thumbnails div {\n  width: 8px;\n  height: 8px;\n  cursor: pointer;\n  background: #aaa;\n  border-radius: 100%;\n}\n\n.thumbnails div.highlighted {\n  background-color: #777;\n}\n\n.slides {\n  margin: 0 16px;\n  display: grid;\n  grid-auto-flow: column;\n  gap: 1rem;\n  width: 540px;\n  padding: 0 0.25rem;\n  height: 720px;\n  overflow-y: auto;\n  overscroll-behavior-x: contain;\n  scroll-snap-type: x mandatory;\n  scrollbar-width: none;\n}\n\n.slides > div {\n  scroll-snap-align: start;\n}\n\n.slides img {\n  width: 540px;\n  object-fit: contain;\n}"},{"lang":"js","text":"const slideGallery = document.querySelector(\".slides\");\nconst slides = slideGallery.querySelectorAll(\"div\");\nconst thumbnailContainer = document.querySelector(\".thumbnails\");\nconst slideCount = slides.length;\nconst slideWidth = 540;\n\nconst highlightThumbnail = () => {\n  thumbnailContainer\n    .querySelectorAll(\"div.highlighted\")\n    .forEach((el) => el.classList.remove(\"highlighted\"));\n  const index = Math.floor(slideGallery.scrollLeft / slideWidth);\n  thumbnailContainer\n    .querySelector(`div[data-id=\"${index}\"]`)\n    .classList.add(\"highlighted\");\n};\n\nconst scrollToElement = (el) => {\n  const index = parseInt(el.dataset.id, 10);\n  slideGallery.scrollTo(index * slideWidth, 0);\n};\n\nthumbnailContainer.innerHTML += [...slides]\n  .map((slide, i) => `<div data-id=\"${i}\"></div>`)\n  .join(\"\");\n\nthumbnailContainer.querySelectorAll(\"div\").forEach((el) => {\n  el.addEventListener(\"click\", () => scrollToElement(el));\n});\n\nslideGallery.addEventListener(\"scroll\", (e) => highlightThumbnail());\n\nhighlightThumbnail();"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Image Gallery With Horizontal Scroll</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n    <script src=\"./script.js\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-css-horizontal-scroll-snap":{"intro":"In this lab, we will explore the concept of horizontal scroll snap in CSS. The lab will guide you through creating a horizontally scrollable container that will snap on elements when scrolling. You will learn how to use the scroll-snap-type property and scroll-snap-align to create a snap effect and how to control the alignment of the snap. By the end of the lab, you will have a good understanding of how to create a sleek and user-friendly horizontal scrolling layout.","steps":[{"title":"Horizontal Scroll Snap","body":["To create a horizontally scrollable container that snaps on elements when scrolling, follow these steps:","• Use display: grid and grid-auto-flow: column to create a horizontal layout. • Use scroll-snap-type: x mandatory and overscroll-behavior-x: contain to create a snap effect on horizontal scroll. • Change scroll-snap-align to either start, stop or center to adjust the snap alignment.","Here's an example HTML and CSS code you can use:"],"code":[{"lang":"text","text":".horizontal-snap {\n  display: grid;\n  grid-auto-flow: column;\n  gap: 1rem;\n  height: calc(180px + 1rem);\n  padding: 1rem;\n  max-width: 480px;\n  margin: 0 auto;\n  overflow-y: auto;\n  overscroll-behavior-x: contain;\n  scroll-snap-type: x mandatory;\n}\n\n.horizontal-snap > a {\n  scroll-snap-align: center;\n}\n\n.horizontal-snap img {\n  width: 180px;\n  max-width: none;\n  object-fit: contain;\n  border-radius: 1rem;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <title>Horizontal Scroll Snap</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <main>\n      <!-- TODO -->\n    </main>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"}};
